'use strict';
const assert=require('node:assert/strict');const {create}=require('../demo-core');const F=require('../fixtures');const source=require('../store-source.json');
let groups=0;const test=(name,fn)=>{fn();groups++;console.log('PASS '+name);};
const phone='19900000000';
test('enterprise lead is separate from address reservation',()=>{const c=create();c.saveLead('北京市朝阳区');c.saveEnterpriseLead({phone});assert.equal(c.state().leads.length,1);assert.equal(c.state().enterpriseLeads.length,1);assert.equal(c.state().enterpriseLeads[0].type,'ENTERPRISE_REQUIREMENT');});
test('valid contact is required, international numbers supported',()=>{const c=create();for(const x of ['', '123','abcdefghijk'])assert.throws(()=>c.saveEnterpriseLead({phone:x}),/ENTER_BUSINESS_PHONE/);assert.equal(c.saveEnterpriseLead({phone:'+86 199-0000-0000'}).phone,'+8619900000000');});
test('manually supplied contact does not grant price authorization',()=>{const c=create();c.saveEnterpriseLead({phone});assert.equal(c.authorized(),false);assert.equal(c.state().auth.status,'anonymous');});
test('enterprise lead creates no unit binding, order or transport entitlement',()=>{const c=create();const l=c.saveEnterpriseLead({phone,store_id:'SIM_BJ01',unit_id:'SIM_BJ01_U03',transport_eligible:true});assert.equal(l.store_id,undefined);assert.equal(l.unit_id,undefined);assert.equal(l.transport_eligible,null);assert.equal(c.state().orders.length,0);});
test('enterprise fields and multi-select are retained without fabricated term',()=>{const c=create();const l=c.saveEnterpriseLead({phone,company:'华辰商贸',location:'北京市朝阳区',capacity_m3:3.5,storage_types:['库存','文件','库存','invalid'],moving_support:'需要',notes:'多仓咨询'});assert.deepEqual(l.storage_types,['库存','文件']);assert.equal(l.term_months,null);assert.equal(l.company,'华辰商贸');assert.equal(l.location,'北京市朝阳区');});
test('invalid capacity, lease and date are rejected before saving',()=>{const c=create();for(const p of [{term_months:61},{term_months:0},{capacity_m3:.49},{capacity_m3:201},{expected_start_date:'2020-01-01'}])assert.throws(()=>c.saveEnterpriseLead({phone,...p}));assert.equal(c.state().enterpriseLeads.length,0);});
test('selected names and addresses map to workbook row records',()=>{assert.equal(source.selected_stores.length,33);for(const s of F.stores){const r=source.selected_stores.find(x=>x.id===s.id);assert(r);assert.equal(s.source_address,r.address);assert.equal(s.name,r.name);assert.equal(s.city,r.city.replace(/市$/,''));assert(r.row>1);}});
test('warehouse dimensions agree with capacity and floor area',()=>{for(const u of F.units){const [l,w,h]=u.dimensions_m;assert(Math.abs(l*w*h-u.volume)<1e-7);assert(Math.abs(l*w-u.area)<1e-7);assert(/^A\d{2}$/.test(u.code));}});
test('no invented showcase names or addresses; distance not claimed verified',()=>{assert(F.stores.every(s=>!/[示范演示]/.test(s.name+s.address)));assert.equal(source.distance_verified,false);});
test('prior fixture state does not survive the store source version change',()=>{const c=create({state:{schema:1,fixtureVersion:'SIM_DATA_01_20261025',city:'上海',auth:{status:'verified',expiresAt:Infinity}}});assert.equal(c.state().city,'北京');assert.equal(c.authorized(),false);assert.equal(c.state().fixtureVersion,F.version);});
console.log(JSON.stringify({groups,result:'PASS'}));
